const { Given, When, Then, After } = require('@cucumber/cucumber');
const assert = require('node:assert');

// ============================================================
// Helpers
// ============================================================

function getDoc() {
  return this.document;
}

function getWindow() {
  return this.window;
}

function query(selector) {
  return this.document.querySelector(selector);
}

function queryAll(selector) {
  return this.document.querySelectorAll(selector);
}

function findTodoItem(label) {
  const items = queryAll.call(this, '.todo-list li');
  for (const li of items) {
    const lbl = li.querySelector('label');
    if (lbl && lbl.textContent.trim() === label) return li;
  }
  return null;
}

function createTodoViaUI(text) {
  const input = query.call(this, '.new-todo');
  if (!input) throw new Error('new-todo input not found');
  input.value = text;
  const event = new this.window.Event('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true });
  input.dispatchEvent(event);
  // Also dispatch keyup and change for good measure
  const keyup = new this.window.Event('keyup', { key: 'Enter', keyCode: 13, which: 13, bubbles: true });
  input.dispatchEvent(keyup);
}

function completeTodoViaUI(label) {
  const li = findTodoItem.call(this, label);
  if (!li) throw new Error(`Todo "${label}" not found`);
  const toggle = li.querySelector('.toggle');
  if (!toggle) throw new Error(`Toggle checkbox not found for "${label}"`);
  toggle.click();
}

// ============================================================
// Given
// ============================================================

Given('the app is loaded', function () {
  // Already loaded by Before hook in world.js
  const main = query.call(this, '.main');
  assert.ok(main, 'App should be loaded');
});

Given('there is a todo {string}', function (title) {
  createTodoViaUI.call(this, title);
  const li = findTodoItem.call(this, title);
  assert.ok(li, `Todo "${title}" should exist`);
});

Given('there are todos {string} and {string}', function (title1, title2) {
  createTodoViaUI.call(this, title1);
  createTodoViaUI.call(this, title2);
  assert.ok(findTodoItem.call(this, title1), `Todo "${title1}" should exist`);
  assert.ok(findTodoItem.call(this, title2), `Todo "${title2}" should exist`);
});

Given('there is a completed todo {string}', function (title) {
  createTodoViaUI.call(this, title);
  completeTodoViaUI.call(this, title);
  const li = findTodoItem.call(this, title);
  assert.ok(li, `Todo "${title}" should exist`);
  assert.ok(li.classList.contains('completed'), `Todo "${title}" should be completed`);
});

Given('there are completed todos {string} and {string}', function (title1, title2) {
  createTodoViaUI.call(this, title1);
  createTodoViaUI.call(this, title2);
  completeTodoViaUI.call(this, title1);
  completeTodoViaUI.call(this, title2);
  assert.ok(findTodoItem.call(this, title1).classList.contains('completed'));
  assert.ok(findTodoItem.call(this, title2).classList.contains('completed'));
});

Given('there are completed todos {string} and active todos {string}', function (completed, active) {
  createTodoViaUI.call(this, completed);
  createTodoViaUI.call(this, active);
  completeTodoViaUI.call(this, completed);
  assert.ok(findTodoItem.call(this, completed).classList.contains('completed'));
  assert.ok(!findTodoItem.call(this, active).classList.contains('completed'));
});

Given('there are no todos', function () {
  const items = queryAll.call(this, '.todo-list li');
  assert.strictEqual(items.length, 0, 'There should be no todos');
});

Given('localStorage has todos with titles {string} and {string}', function (title1, title2) {
  const todos = [
    { id: '1', title: title1, completed: false },
    { id: '2', title: title2, completed: false }
  ];
  this.window.localStorage.setItem('todos-vanillajs', JSON.stringify(todos));
});

// ============================================================
// When
// ============================================================

When('I type {string} into the new-todo input and press Enter', function (text) {
  createTodoViaUI.call(this, text);
});

When('I click the toggle checkbox on the {string} todo', function (label) {
  completeTodoViaUI.call(this, label);
});

When('I click the destroy button on the {string} todo', function (label) {
  const li = findTodoItem.call(this, label);
  if (!li) throw new Error(`Todo "${label}" not found`);
  const destroy = li.querySelector('.destroy');
  if (!destroy) throw new Error(`Destroy button not found for "${label}"`);
  destroy.click();
});

When('I double-click the label of {string}', function (label) {
  const li = findTodoItem.call(this, label);
  if (!li) throw new Error(`Todo "${label}" not found`);
  const labelEl = li.querySelector('label');
  if (!labelEl) throw new Error(`Label not found for "${label}"`);
  const dblClick = new this.window.MouseEvent('dblclick', { bubbles: true });
  labelEl.dispatchEvent(dblClick);
});

When('I change the edit input to {string} and blur', function (newText) {
  const editInput = query.call(this, '.todo-list li.editing .edit');
  if (!editInput) throw new Error('No todo in editing mode');
  editInput.value = newText;
  const blurEvent = new this.window.Event('blur', { bubbles: true });
  editInput.dispatchEvent(blurEvent);
});

When('I change the edit input to {string} and press Enter', function (newText) {
  const editInput = query.call(this, '.todo-list li.editing .edit');
  if (!editInput) throw new Error('No todo in editing mode');
  editInput.value = newText;
  const keydown = new this.window.Event('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true });
  editInput.dispatchEvent(keydown);
});

When('I change the edit input to {string} and press Escape', function (newText) {
  const editInput = query.call(this, '.todo-list li.editing .edit');
  if (!editInput) throw new Error('No todo in editing mode');
  editInput.value = newText;
  const keydown = new this.window.Event('keydown', { key: 'Escape', keyCode: 27, which: 27, bubbles: true });
  editInput.dispatchEvent(keydown);
});

When('I click the toggle-all checkbox', function () {
  const toggleAll = query.call(this, '.toggle-all');
  if (!toggleAll) throw new Error('toggle-all checkbox not found');
  toggleAll.click();
});

When('I click the clear-completed button', function () {
  const btn = query.call(this, '.clear-completed');
  if (!btn) throw new Error('clear-completed button not found');
  btn.click();
});

When('I view the app', function () {
  // App is already loaded, this is a no-op for the step
});

When('I complete the todo {string}', function (label) {
  completeTodoViaUI.call(this, label);
});

When('I navigate to {string}', function (hash) {
  this.navigate(hash);
});

When('I navigate to the default route', function () {
  this.navigate('#/');
});

When('the app is reloaded', function () {
  // Reload by disposing and re-creating the app
  return this.disposeApp().then(() => {
    this.loadApp();
  });
});

When('I check localStorage', function () {
  // Just a set-up step, nothing to do
});

When('I inspect localStorage', function () {
  // Just a set-up step, nothing to do
});

// ============================================================
// Then
// ============================================================

Then('I should see {string} in the todo list', function (label) {
  const li = findTodoItem.call(this, label);
  assert.ok(li, `Expected to see "${label}" in the todo list`);
});

Then('I should not see {string} in the todo list', function (label) {
  const li = findTodoItem.call(this, label);
  assert.ok(!li, `Expected not to see "${label}" in the todo list`);
});

Then('the new-todo input should be cleared', function () {
  const input = query.call(this, '.new-todo');
  assert.strictEqual(input.value, '', 'new-todo input should be cleared');
});

Then('the todo list should be empty', function () {
  const items = queryAll.call(this, '.todo-list li');
  assert.strictEqual(items.length, 0, 'Todo list should be empty');
});

Then('the {string} todo should have the completed class', function (label) {
  const li = findTodoItem.call(this, label);
  assert.ok(li, `Todo "${label}" should exist`);
  assert.ok(li.classList.contains('completed'), `Todo "${label}" should have completed class`);
});

Then('the {string} todo should not have the completed class', function (label) {
  const li = findTodoItem.call(this, label);
  if (li) {
    assert.ok(!li.classList.contains('completed'), `Todo "${label}" should not have completed class`);
  }
});

Then('the todo should be in editing mode', function () {
  const editing = query.call(this, '.todo-list li.editing');
  assert.ok(editing, 'A todo should be in editing mode');
});

Then('all todos should be completed', function () {
  const items = queryAll.call(this, '.todo-list li');
  assert.ok(items.length > 0, 'There should be todos');
  for (const li of items) {
    assert.ok(li.classList.contains('completed'), 'All todos should be completed');
  }
});

Then('no todos should be completed', function () {
  const items = queryAll.call(this, '.todo-list li');
  for (const li of items) {
    assert.ok(!li.classList.contains('completed'), 'No todos should be completed');
  }
});

Then('the toggle-all checkbox should be checked', function () {
  const toggleAll = query.call(this, '.toggle-all');
  assert.ok(toggleAll, 'toggle-all checkbox should exist');
  assert.ok(toggleAll.checked, 'toggle-all checkbox should be checked');
});

Then('the clear-completed button should be hidden', function () {
  const btn = query.call(this, '.clear-completed');
  if (!btn) {
    // Button doesn't exist at all, that's fine
    return;
  }
  // The button should be hidden (CSS class or style)
  const style = this.window.getComputedStyle(btn);
  assert.strictEqual(style.display, 'none', 'clear-completed button should be hidden');
});

Then('the todo-count should show {string}', function (expected) {
  const countEl = query.call(this, '.todo-count');
  assert.ok(countEl, 'todo-count element should exist');
  assert.strictEqual(countEl.textContent.trim(), expected, `todo-count should show "${expected}"`);
});

Then('the main section should be hidden', function () {
  const main = query.call(this, '.main');
  assert.ok(main, 'main section should exist');
  const style = this.window.getComputedStyle(main);
  assert.strictEqual(style.display, 'none', 'main section should be hidden');
});

Then('the footer section should be hidden', function () {
  const footer = query.call(this, '.footer');
  assert.ok(footer, 'footer section should exist');
  const style = this.window.getComputedStyle(footer);
  assert.strictEqual(style.display, 'none', 'footer section should be hidden');
});

Then('the main section should be visible', function () {
  const main = query.call(this, '.main');
  assert.ok(main, 'main section should exist');
  const style = this.window.getComputedStyle(main);
  assert.notStrictEqual(style.display, 'none', 'main section should be visible');
});

Then('the footer section should be visible', function () {
  const footer = query.call(this, '.footer');
  assert.ok(footer, 'footer section should exist');
  const style = this.window.getComputedStyle(footer);
  assert.notStrictEqual(style.display, 'none', 'footer section should be visible');
});

Then('localStorage should contain todos with titles {string} and {string}', function (title1, title2) {
  const data = this.window.localStorage.getItem('todos-vanillajs');
  assert.ok(data, 'localStorage should contain todos');
  const todos = JSON.parse(data);
  const titles = todos.map(t => t.title);
  assert.ok(titles.includes(title1), `localStorage should contain "${title1}"`);
  assert.ok(titles.includes(title2), `localStorage should contain "${title2}"`);
});

Then('the todos should be stored under the key {string}', function (key) {
  const data = this.window.localStorage.getItem(key);
  assert.ok(data, `localStorage should have key "${key}"`);
});

Then('each todo should have {string}, {string}, and {string} fields', function (field1, field2, field3) {
  const data = this.window.localStorage.getItem('todos-vanillajs');
  assert.ok(data, 'localStorage should contain todos');
  const todos = JSON.parse(data);
  assert.ok(Array.isArray(todos), 'todos should be an array');
  for (const todo of todos) {
    assert.ok(todo.hasOwnProperty(field1), `Todo should have "${field1}" field`);
    assert.ok(todo.hasOwnProperty(field2), `Todo should have "${field2}" field`);
    assert.ok(todo.hasOwnProperty(field3), `Todo should have "${field3}" field`);
  }
});

Then('the {string} filter link should have the selected class', function (filterLabel) {
  const filters = queryAll.call(this, '.filters a');
  let found = null;
  for (const a of filters) {
    if (a.textContent.trim() === filterLabel) {
      found = a;
      break;
    }
  }
