(function () {
	'use strict';

	var ENTER_KEY = 13;
	var ESCAPE_KEY = 27;
	var STORAGE_KEY = 'todos-vanillajs';

	// -----------------------------------------------------------------------
	// Store
	// -----------------------------------------------------------------------

	/**
	 * @planks("the app is loaded")
	 * @planks("the app is reloaded")
	 * @planks("localStorage has todos with titles {string} and {string}")
	 */
	function Store(key) {
		this.key = key;
	}

	/**
	 * @planks("the app is loaded")
	 * @planks("the app is reloaded")
	 * @planks("localStorage has todos with titles {string} and {string}")
	 */
	Store.prototype.getTodos = function () {
		var data = localStorage.getItem(this.key);
		return data ? JSON.parse(data) : [];
	};

	/**
	 * @planks("I type {string} into the new-todo input and press Enter")
	 * @planks("I click the toggle checkbox on the {string} todo")
	 * @planks("I click the destroy button on the {string} todo")
	 * @planks("I click the toggle-all checkbox")
	 * @planks("I click the clear-completed button")
	 * @planks("I change the edit input to {string} and blur")
	 * @planks("I change the edit input to {string} and press Enter")
	 */
	Store.prototype.save = function (todos) {
		localStorage.setItem(this.key, JSON.stringify(todos));
	};

	// -----------------------------------------------------------------------
	// App
	// -----------------------------------------------------------------------

	/**
	 * @planks("the app is loaded")
	 * @planks("the app is reloaded")
	 */
	function App() {
		this.store = new Store(STORAGE_KEY);
		this.todos = [];
		this.filter = 'all';
		this.todoList = document.querySelector('.todo-list');
		this.main = document.querySelector('.main');
		this.footer = document.querySelector('.footer');
		this.newTodo = document.querySelector('.new-todo');
		this.toggleAll = document.querySelector('.toggle-all');
		this.todoCount = document.querySelector('.todo-count');
		this.clearCompleted = document.querySelector('.clear-completed');
		this.filters = document.querySelectorAll('.filters a');
	}

	/**
	 * @planks("the app is loaded")
	 * @planks("the app is reloaded")
	 */
	App.prototype.init = function () {
		this.todos = this.store.getTodos();
		this.bindEvents();
		this.setFilterFromHash();
		this.render();
	};

	App.prototype.bindEvents = function () {
		var self = this;

		// New todo
		this.newTodo.addEventListener('keydown', function (e) {
			if (e.keyCode === ENTER_KEY) {
				self.addTodo();
			}
		});

		// Toggle all
		this.toggleAll.addEventListener('change', function () {
			self.toggleAllTodos(this.checked);
		});

		// Clear completed
		this.clearCompleted.addEventListener('click', function () {
			self.clearCompletedTodos();
		});

		// Todo list events (delegation)
		this.todoList.addEventListener('click', function (e) {
			var li = e.target.closest('li');
			if (!li) return;

			if (e.target.classList.contains('toggle')) {
				self.toggleTodo(li.dataset.id);
			}

			if (e.target.classList.contains('destroy')) {
				self.destroyTodo(li.dataset.id);
			}
		});

		// Double-click to edit (delegation)
		this.todoList.addEventListener('dblclick', function (e) {
			var label = e.target.closest('label');
			if (!label) return;
			var li = label.closest('li');
			if (!li) return;
			self.editTodo(li);
		});

		// Edit input events (delegation)
		this.todoList.addEventListener('keydown', function (e) {
			var editInput = e.target.closest('.edit');
			if (!editInput) return;
			var li = editInput.closest('li');
			if (!li) return;

			if (e.keyCode === ENTER_KEY) {
				self.commitEdit(li, editInput.value);
			} else if (e.keyCode === ESCAPE_KEY) {
				self.cancelEdit(li);
			}
		});

		this.todoList.addEventListener('blur', function (e) {
			var editInput = e.target.closest('.edit');
			if (!editInput) return;
			var li = editInput.closest('li');
			if (!li) return;
			self.commitEdit(li, editInput.value);
		}, true);

		// Routing
		window.addEventListener('hashchange', function () {
			self.setFilterFromHash();
			self.render();
		});
	};

	/**
	 * @planks("I navigate to {string}")
	 * @planks("I navigate to the default route")
	 * @planks("the app is loaded")
	 * @planks("the app is reloaded")
	 */
	App.prototype.setFilterFromHash = function () {
		var hash = window.location.hash;
		if (hash === '#/active') {
			this.filter = 'active';
		} else if (hash === '#/completed') {
			this.filter = 'completed';
		} else {
			this.filter = 'all';
		}
	};

	/**
	 * @planks("I should see {string} in the todo list")
	 * @planks("I should not see {string} in the todo list")
	 */
	App.prototype.getFilteredTodos = function () {
		if (this.filter === 'active') {
			return this.todos.filter(function (t) { return !t.completed; });
		}
		if (this.filter === 'completed') {
			return this.todos.filter(function (t) { return t.completed; });
		}
		return this.todos;
	};

	/**
	 * @planks("I type {string} into the new-todo input and press Enter")
	 * @planks("I type {string} into the new-todo input and press Enter")
	 */
	App.prototype.addTodo = function () {
		var title = this.newTodo.value.trim();
		if (title === '') return;
		this.todos.push({
			id: Date.now() + Math.random(),
			title: title,
			completed: false
		});
		this.store.save(this.todos);
		this.newTodo.value = '';
		this.render();
	};

	/**
	 * @planks("I click the toggle checkbox on the {string} todo")
	 */
	App.prototype.toggleTodo = function (id) {
		for (var i = 0; i < this.todos.length; i++) {
			if (this.todos[i].id == id) {
				this.todos[i].completed = !this.todos[i].completed;
				break;
			}
		}
		this.store.save(this.todos);
		this.render();
	};

	/**
	 * @planks("I click the destroy button on the {string} todo")
	 * @planks("I change the edit input to {string} and press Enter")
	 * @planks("I change the edit input to {string} and blur")
	 */
	App.prototype.destroyTodo = function (id) {
		this.todos = this.todos.filter(function (t) { return t.id != id; });
		this.store.save(this.todos);
		this.render();
	};

	/**
	 * @planks("I click the toggle-all checkbox")
	 */
	App.prototype.toggleAllTodos = function (checked) {
		for (var i = 0; i < this.todos.length; i++) {
			this.todos[i].completed = checked;
		}
		this.store.save(this.todos);
		this.render();
	};

	/**
	 * @planks("I click the clear-completed button")
	 */
	App.prototype.clearCompletedTodos = function () {
		this.todos = this.todos.filter(function (t) { return !t.completed; });
		this.store.save(this.todos);
		this.render();
	};

	/**
	 * @planks("I double-click the label of {string}")
	 */
	App.prototype.editTodo = function (li) {
		li.classList.add('editing');
		var editInput = li.querySelector('.edit');
		editInput.value = li.querySelector('label').textContent;
		editInput.focus();
		// Set cursor at end
		editInput.selectionStart = editInput.selectionEnd = editInput.value.length;
	};

	/**
	 * @planks("I change the edit input to {string} and blur")
	 * @planks("I change the edit input to {string} and press Enter")
	 */
	App.prototype.commitEdit = function (li, value) {
		var title = value.trim();
		var id = li.dataset.id;

		if (title === '') {
			this.destroyTodo(id);
			return;
		}

		for (var i = 0; i < this.todos.length; i++) {
			if (this.todos[i].id == id) {
				this.todos[i].title = title;
				break;
			}
		}
		this.store.save(this.todos);
		li.classList.remove('editing');
		this.render();
	};

	/**
	 * @planks("I change the edit input to {string} and press Escape")
	 */
	App.prototype.cancelEdit = function (li) {
		li.classList.remove('editing');
	};

	// -----------------------------------------------------------------------
	// Render
	// -----------------------------------------------------------------------

	/**
	 * @planks("I should see {string} in the todo list")
	 * @planks("I should not see {string} in the todo list")
	 * @planks("the todo list should be empty")
	 * @planks("the {string} todo should have the completed class")
	 * @planks("the {string} todo should not have the completed class")
	 * @planks("the todo should be in editing mode")
	 * @planks("all todos should be completed")
	 * @planks("no todos should be completed")
	 * @planks("the toggle-all checkbox should be checked")
	 * @planks("the clear-completed button should be hidden")
	 * @planks("the todo-count should show {string}")
	 * @planks("the main section should be hidden")
	 * @planks("the footer section should be hidden")
	 * @planks("the main section should be visible")
	 * @planks("the footer section should be visible")
	 * @planks("the {string} filter link should have the selected class")
	 * @planks("the {string} todo should not be in editing mode")
	 */
	App.prototype.render = function () {
		var filtered = this.getFilteredTodos();
		var html = '';

		for (var i = 0; i < filtered.length; i++) {
			var todo = filtered[i];
			var completedClass = todo.completed ? ' class="completed"' : '';
			var checked = todo.completed ? ' checked' : '';
			html += '<li' + completedClass + ' data-id="' + todo.id + '">';
			html += '<div class="view">';
			html += '<input class="toggle" type="checkbox"' + checked + '>';
			html += '<label>' + this.escapeHtml(todo.title) + '</label>';
			html += '<button class="destroy"></button>';
			html += '</div>';
			html += '<input class="edit" value="' + this.escapeHtml(todo.title) + '">';
			html += '</li>';
		}

		this.todoList.innerHTML = html;

		// Main and footer visibility
		var hasTodos = this.todos.length > 0;
		this.main.style.display = hasTodos ? 'block' : 'none';
		this.footer.style.display = hasTodos ? 'block' : 'none';

		// Toggle-all checkbox state
		var allCompleted = this.todos.length > 0 && this.todos.every(function (t) { return t.completed; });
		this.toggleAll.checked = allCompleted;

		// Clear completed visibility
		var hasCompleted = this.todos.some(function (t) { return t.completed; });
		this.clearCompleted.style.display = hasCompleted ? 'block' : 'none';

		// Update count
		var activeCount = this.todos.filter(function (t) { return !t.completed; }).length;
		var itemWord = activeCount === 1 ? 'item' : 'items';
		this.todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + itemWord + ' left';

		// Update filter links
		for (var j = 0; j < this.filters.length; j++) {
			var a = this.filters[j];
			var href = a.getAttribute('href');
			if (href === '#/') {
				a.classList.toggle('selected', this.filter === 'all');
			} else if (href === '#/active') {
				a.classList.toggle('selected', this.filter === 'active');
			} else if (href === '#/completed') {
				a.classList.toggle('selected', this.filter === 'completed');
			}
		}
	};

	App.prototype.escapeHtml = function (str) {
		var div = document.createElement('div');
		div.appendChild(document.createTextNode(str));
		return div.innerHTML;
	};

	// -----------------------------------------------------------------------
	// Bootstrap
	// -----------------------------------------------------------------------

	var app = new App();

	if (document.readyState === 'loading') {
		document.addEventListener('DOMContentLoaded', function () { app.init(); });
	} else {
		app.init();
	}
})();
